import * as React from "react"
import { cn } from "@/lib/utils"

// Dark Neon AI Empty State: centered content with icon, title, description, and optional action
// Dark theme: rounded-[0.875rem] dashed border, near-black inner well, neon-tinted icon chip

interface EmptyStateProps extends React.HTMLAttributes<HTMLDivElement> {
  icon?: React.ReactNode
  title: string
  description?: string
  action?: React.ReactNode
}

function EmptyState({
  icon,
  title,
  description,
  action,
  className,
  ...props
}: EmptyStateProps) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-4 rounded-[0.875rem] border border-dashed border-border bg-card p-10 text-center",
        className
      )}
      {...props}
    >
      {icon && (
        <div className="flex h-12 w-12 items-center justify-center rounded-[0.75rem] bg-background ring-1 ring-border [box-shadow:var(--shadow-inset)] text-primary">
          {icon}
        </div>
      )}
      <div className="flex flex-col gap-1">
        <p className="text-sm font-medium text-foreground">{title}</p>
        {description && (
          <p className="text-sm text-muted-foreground">{description}</p>
        )}
      </div>
      {action && <div>{action}</div>}
    </div>
  )
}

export { EmptyState }
export type { EmptyStateProps }
